from qlib import eq_check as _eqc


def _C(line, *ats, **at):
    """A line that holds only at given values (a slope, an intercept, a point): checked here, then left unchecked ('~')."""
    for a in (ats or (at,)): _eqc(line, {k: float(v) for k, v in a.items()})
    return '~' + line
