 ('2-10', 8, 'פתרו את המשוואה הבאה. גם האיברים בלי מכנה מורחבים.', '{f|3x-2|4}+2=x', '6', [('~4', 'המכנה המשותף הוא 4. גם 2 וגם $x$ הם שברים עם מכנה 1.'), ('{f|3x-2|4}+{f|8|4} = {f|4x|4}', 'מרחיבים: $2 = 8/4$, ו-$x = 4x/4$.'), ('{f|3x+6|4} = {f|4x|4} @·4', 'מחברים מונים: $-2 + 8 = 6$. כופלים את שני האגפים ב-4.'), ('3x+6 = 4x', 'המכנים נעלמים.'), ('6 = 4x-3x', 'מעבירים את $3x$ ימינה. המקדם של $x$ חיובי.'), ('x = 6', 'מכנסים.')]),
 ('2-11', 8, 'פתרו את המשוואה הבאה. רשמו קודם את תחום ההגדרה.', '{f|5|x}-{f|1|2x}={f|3|4}', '6', [('~x ≠ 0', 'תחום ההגדרה: המכנים $x$ ו-$2x$ לא יכולים להיות אפס.'), ('~4x', 'המכנה המשותף של $x$, $2x$ ו-4 הוא $4x$.'), ('{f|4·5|4·x}-{f|2·1|2·2x} = {f|3·x|4·x}', 'מרחיבים: את $5/x$ ב-4, את $1/(2x)$ ב-2, ואת $3/4$ ב-$x$.'), ('{f|20-2|4x} = {f|3x|4x} @·4x', 'מחסרים מונים. כופלים את שני האגפים ב-$4x$.'), ('18 = 3x @:3', 'המכנים נעלמים.'), ('x = 6', 'מחלקים ב-3. 6 שונה מ-0, ולכן בתוך התחום.')]),
 ('2-12', 8, 'פתרו את המשוואה הבאה. רשמו קודם את תחום ההגדרה.', '{f|2x+1|x-1}=3', '4', [('~x ≠ 1', 'תחום ההגדרה: $x = 1$ מאפס את המכנה.'), ('{f|2x+1|x-1} = {f|3(x-1)|x-1} @·(x-1)', 'גם 3 הוא שבר: מרחיבים אותו למכנה $x - 1$. כופלים את שני האגפים ב-$(x - 1)$.'), ('2x+1 = 3x-3', 'המכנים נעלמים. פותחים סוגריים.'), ('1+3 = 3x-2x', 'מעבירים: $2x$ ימינה, $-3$ שמאלה. המקדם של $x$ חיובי.'), ('x = 4', 'מכנסים. 4 שונה מ-1, ולכן בתוך התחום.')]),
 ('2-13', 9, 'פתרו את מערכת המשוואות בשיטת ההצבה.', '3x+2y=16;x-2y=0', {'x': '4', 'y': '2'}, [('x = {h|2y}', 'שלב 1, מבודדים: במשוואה השנייה ל-$x$ יש מקדם 1. מעבירים את $-2y$ ימינה.'), ('3·{h|2y}+2y = 16', 'שלב 2, מציבים את $2y$ במקום $x$ במשוואה הראשונה.'), ('8y = 16 @:8', 'שלב 3, פותרים: $6y + 2y = 8y$.'), ('y = 2', 'מחלקים ב-8.'), ('x = 2·2 = 4', 'שלב 4, חוזרים לביטוי של $x$.')]),
 ('2-14', 9, 'פתרו את מערכת המשוואות בשיטת ההצבה.', 'y=3x-1;2x+y=9', {'x': '2', 'y': '5'}, [('~', 'שלב 1: במשוואה הראשונה $y$ כבר מבודד.'), ('2x+{h|(3x-1)} = 9', 'שלב 2, מציבים $3x - 1$ במקום $y$ במשוואה השנייה, בסוגריים.'), ('2x+3x-1 = 9', 'שלב 3, פותחים סוגריים.'), ('5x = 9+1', 'מכנסים, ומעבירים את $-1$ לאגף הימני.'), ('5x = 10 @:5', 'מחשבים.'), ('x = 2', 'מחלקים ב-5.'), ('y = 3·2-1 = 5', 'שלב 4, חוזרים לביטוי של $y$.')]),
 ('2-15', 9, 'פתרו את מערכת המשוואות בשיטת ההצבה. בודדו את $x$ במשוואה הראשונה, בשני צעדים.', '2x+6y=8;3x+5y=4', {'x': '-2', 'y': '2'}, [('2x = 8-6y', 'שלב 1, מבודדים את $x$: קודם מעבירים את $6y$ לאגף השני.'), ('x = {f|8|2}-{f|6|2}y', '$x$ מוכפל ב-2: מחלקים ב-2 כל איבר באגף הימני.'), ('x = {h|4-3y}', 'מצמצמים.'), ('3{h|(4-3y)}+5y = 4', 'שלב 2, מציבים במשוואה השנייה, בסוגריים.'), ('12-9y+5y = 4', 'שלב 3, פותחים סוגריים.'), ('12-4 = 4y', 'מכנסים ($-4y$), ומעבירים: $-4y$ ימינה, 4 שמאלה.'), ('8 = 4y @:4', 'מחשבים.'), ('y = 2', 'מחלקים ב-4.'), ('x = 4-3·2 = -2', 'שלב 4, חוזרים לביטוי של $x$.')]),
 ('2-16', 10, 'פתרו את מערכת המשוואות בשיטת השוואת המקדמים.', 'x+y=10;x-y=4', {'x': '7', 'y': '3'}, [('~', 'המקדם של $x$ כבר זהה: 1 בשתי המשוואות. אין צורך לכפול.'), ('(x+y)-(x-y) = 10-4', 'מחסרים: אגף שמאל מאגף שמאל, אגף ימין מאגף ימין.'), ('{x|x}+y-{x|x}+y = 6', 'פותחים סוגריים. $-(-y) = +y$, ו-$x - x = 0$.'), ('2y = 6 @:2', 'מכנסים.'), ('y = 3', 'מחלקים ב-2.'), ('x+3 = 10', 'מציבים $y = 3$ במשוואה הראשונה.'), ('x = 7', 'מעבירים: $x = 10 - 3$.')]),
 ('2-17', 10, 'פתרו את מערכת המשוואות בשיטת השוואת המקדמים.', '2x+5y=16;2x+y=8', {'x': '3', 'y': '2'}, [('~', 'המקדם של $x$ כבר זהה: 2 בשתי המשוואות.'), ('(2x+5y)-(2x+y) = 16-8', 'מחסרים אגף מאגף.'), ('{x|2x}+5y-{x|2x}-y = 8', 'פותחים סוגריים. $2x - 2x = 0$.'), ('4y = 8 @:4', 'מכנסים: $5y - y = 4y$.'), ('y = 2', 'מחלקים ב-4.'), ('2x+2 = 8', 'מציבים $y = 2$ במשוואה השנייה.'), ('2x = 6 @:2', 'מעבירים את 2.'), ('x = 3', 'מחלקים ב-2.')]),
 ('2-18', 10, 'פתרו את מערכת המשוואות בשיטת השוואת המקדמים.', '3x+2y=7;5x+4y=13', {'x': '1', 'y': '2'}, [('3x+2y = 7 @·2', 'נשווה את המקדם של $y$: בשנייה הוא 4, ולכן כופלים את הראשונה ב-2.'), ('6x+4y = 14', 'כל איבר כפול 2, גם 7.'), ('(6x+4y)-(5x+4y) = 14-13', 'מחסרים את השנייה מהחדשה: אגף מאגף.'), ('6x+{x|4y}-5x-{x|4y} = 1', 'פותחים סוגריים. $4y - 4y = 0$.'), ('x = 1', 'מכנסים: $6x - 5x = x$.'), ('3+2y = 7', 'מציבים $x = 1$ במשוואה הראשונה.'), ('2y = 4 @:2', 'מעבירים את 3.'), ('y = 2', 'מחלקים ב-2.')]),
 ('2-19', 10, 'ארבע מחברות ושלושה עטים עולים 46 ש״ח. שתי מחברות וחמישה עטים עולים 44 ש״ח. מה המחיר של מחברת, ומה המחיר של עט? נסמן מחברת ב-$x$ ועט ב-$y$, ופתרו בשיטת השוואת המקדמים.', '~4x+3y=46;2x+5y=44', {'x': '7', 'y': '6'}, [('4x+3y = 46', 'הקנייה הראשונה.'), ('2x+5y = 44 @·2', 'הקנייה השנייה. נשווה את המקדם של $x$ ל-4: כופלים אותה ב-2.'), ('4x+10y = 88', 'כל איבר כפול 2.'), ('(4x+10y)-(4x+3y) = 88-46', 'מחסרים את הקנייה הראשונה מהחדשה: אגף מאגף.'), ('{x|4x}+10y-{x|4x}-3y = 42', 'פותחים סוגריים. $4x - 4x = 0$.'), ('7y = 42 @:7', 'מכנסים.'), ('y = 6', 'מחלקים ב-7: עט עולה 6 ש״ח.'), ('4x+18 = 46', 'מציבים $y = 6$ במשוואה הראשונה.'), ('4x = 28 @:4', 'מעבירים את 18.'), ('x = 7', 'מחברת עולה 7 ש״ח.')]),
 ('3-1', 11, 'תקציב השיווק של חברה הוא 2,400 אלף ש״ח, ו-35% ממנו מוקצים לפרסום ברשת. כמה כסף, באלפי ש״ח, מוקצה לפרסום ברשת?', '~0.35*2400', '840', [('=0.35*2400', '35% הם $35/100 = 0.35$.'), ('=840', 'באלפי ש״ח.')]),
 ('3-2', 11, 'מחיר של מוצר הוא 1,500 ש״ח. המחיר ירד ב-20%, ואחר כך עלה ב-20%. מה המחיר הסופי?', '~1500*0.8*1.2', '1440', [('1500*0.8 = 1200', 'אחרי הירידה.'), ('1200*1.2 = 1440', 'העלייה היא 20% מ-1,200, ולא מ-1,500.'), ('=1440', 'המחיר הסופי נמוך מהמקורי.')]),
 ('3-3', 11, 'המכירות של חנות עלו מ-250 יחידות בחודש ל-310 יחידות בחודש. בכמה אחוזים עלו המכירות?', '~(310/250-1)*100', '24', [('310/250 = 1.24', 'החדש חלקי הקודם.'), ('1.24-1 = 0.24', 'מחסירים 1.'), ('=24', 'כופלים ב-100: עלייה של 24%.')]),
 ('3-4', 11, 'אחרי הנחה של 15%, דני שילם על מעיל 425 ש״ח. מה היה המחיר לפני ההנחה? נסמן אותו ב-$x$.', '~0.85x=425', '500', [('~0.85', 'הנחה של 15%: המקדם הוא $1 - 0.15 = 0.85$.'), ('0.85x = 425', 'המחיר המקורי כפול המקדם שווה למה ששילם.'), ('x = 425/0.85', 'מחלקים את שני האגפים ב-0.85.'), ('x = 500', 'המחיר לפני ההנחה.')]),
 ('3-5', 11, 'מחיר של מוצר עלה ב-25%, ואחר כך עלה שוב ב-10%. אחרי שתי ההעלאות המחיר הוא 550 ש״ח. מה היה המחיר ההתחלתי? נסמן אותו ב-$x$.', '~1.375x=550', '400', [('~1.25x', 'אחרי העלייה הראשונה, 25%: כופלים במקדם 1.25.'), ('1.25x*1.1 = 1.375x', 'אחרי העלייה השנייה, 10%: כופלים שוב, ב-1.1.'), ('1.375x = 550 @:1.375', 'המחיר בסוף ידוע: משוואה.'), ('x = {f|550|1.375} = 400', 'מחלקים את שני האגפים ב-1.375.'), ('400*1.25*1.1 = 550', 'בדיקה: $400·1.25 = 500$, ו-$500·1.1 = 550$.')]),
 ('3-6', 13, 'נתונה הפונקציה $f(x) = x^2 - 4x + 3$. חשבו את $f(-1)$.', '~', '8', [('=(-1)^2-4*(-1)+3', 'מציבים $-1$ במקום כל $x$, בסוגריים.'), ('=1+4+3', 'חזקה: $(-1)^2 = 1$. כפל: $-4·(-1) = +4$.'), ('=8', 'מחברים: $f(-1) = 8$.')]),
 ('3-7', 13, 'נתונה הפונקציה $f(x) = 3x + 6$. לאיזה $x$ מתקיים $f(x) = 0$?', '3x+6=0', '-2', [('3x = -6 @:3', 'כותבים משוואה, $3x + 6 = 0$, ומעבירים את 6 לאגף הימני. הוא הופך ל-$-6$.'), ('x = -2', 'מחלקים ב-3.'), ('3*(-2)+6 = 0', 'בדיקה: $f(-2) = 0$.')]),
 ('3-8', 13, 'מהו תחום ההגדרה של הפונקציה $f(x) = {f|4|2x+10}$?', '~', 'x≠-5', [(_C('2x+10 = 0', x=-5), 'המכנה לא יכול להיות 0: משווים אותו לאפס.'), (_C('2x = -10 @:2', x=-5), 'מעבירים את 10 לאגף הימני.'), (_C('x = -5', x=-5), 'מחלקים ב-2. זה המספר האסור.'), ('~x ≠ -5', 'תחום ההגדרה: כל המספרים, חוץ מ-$-5$.')]),
 ('3-9', 14, 'מצאו את נקודות החיתוך של הישר $y = 4x - 8$ עם הצירים.', '~', '(0,-8)_,_(2,0)', [(_C('y = 4·0-8 = -8', y=-8), 'חיתוך עם ציר $y$: מציבים $x = 0$.'), (_C('0 = 4x-8', x=2), 'חיתוך עם ציר $x$: מציבים $y = 0$.'), (_C('8 = 4x @:4', x=2), 'מעבירים את $-8$ לאגף השמאלי, כך שהמקדם של $x$ חיובי.'), (_C('2 = x', x=2), 'מחלקים ב-4. הנקודות: $(0, -8)$ ו-$(2, 0)$.')]),
 ('3-10', 14, 'מצאו את משוואת הישר שעובר דרך הנקודות $(1, 2)$ ו-$(4, 11)$.', '~', 'y=3x-1', [(_C('m = {f|11-2|4-1} = {f|9|3} = 3', m=3), 'שלב 1, השיפוע: ההפרש ב-$y$ חלקי ההפרש ב-$x$.'), (_C('2 = 3·1+b', b=-1), 'שלבים 2 ו-3: מציבים $m = 3$ ואת הנקודה $(1, 2)$ בתבנית $y = mx + b$.'), (_C('2-3 = b', b=-1), 'מעבירים את 3 לאגף השמאלי.'), (_C('b = -1', b=-1), 'מחשבים: $2 - 3 = -1$.'), (_C('y = 3x-1', dict(x=1, y=2), dict(x=4, y=11)), 'שלב 4: בודקים בנקודה השנייה, $3·4 - 1 = 11$.')]),
 ('3-11', 14, 'מצאו את משוואת הישר שעובר דרך הנקודות $(-2, 7)$ ו-$(2, -1)$.', '~', 'y=-2x+3', [(_C('m = {f|-1-7|2-(-2)} = {f|-8|4} = -2', m=-2), 'שלב 1, השיפוע. במכנה: $2 - (-2) = 4$. השיפוע שלילי: הישר יורד.'), (_C('7 = -2·(-2)+b', b=3), 'מציבים $m = -2$ ואת $(-2, 7)$, בסוגריים.'), (_C('7 = 4+b', b=3), '$-2·(-2) = +4$.'), (_C('7-4 = b', b=3), 'מעבירים את 4 לאגף השמאלי.'), (_C('y = -2x+3', dict(x=-2, y=7), dict(x=2, y=-1)), 'בדיקה בנקודה השנייה: $-2·2 + 3 = -1$.')]),
 ('3-12', 14, 'התשלום על חשמל במשרד הוא קו ישר בכמות הקוט״ש. על 200 קוט״ש שילמו 150 ש״ח, ועל 500 קוט״ש שילמו 300 ש״ח. מצאו את משוואת התשלום. מהו המחיר לקוט״ש, ומהו התשלום הקבוע?', '~', 'y=0.5x+50', [('~(200, 150)_,_(500, 300)', 'כל חודש הוא נקודה: $x$ קוט״ש, $y$ ש״ח.'), (_C('m = {f|300-150|500-200} = {f|150|300} = 0.5', m=0.5), 'השיפוע: 0.5 ש״ח לכל קוט״ש.'), (_C('150 = 0.5·200+b', b=50), 'מציבים $m$ ואת $(200, 150)$.'), (_C('150-100 = b', b=50), '$0.5·200 = 100$. מעבירים אותו לאגף השמאלי.'), (_C('y = 0.5x+50', dict(x=200, y=150), dict(x=500, y=300)), 'תשלום קבוע של 50 ש״ח. בדיקה: $0.5·500 + 50 = 300$.')]),
 ('3-13', 15, 'מצאו את משוואת הישר שמקביל לישר $y = 4x - 1$ ועובר דרך הנקודה $(2, 5)$.', '~', 'y=4x-3', [(_C('m = 4', m=4), 'מקביל: אותו שיפוע.'), (_C('5 = 4·2+b', b=-3), 'מציבים $m = 4$ ואת $(2, 5)$.'), (_C('5-8 = b', b=-3), 'מעבירים את 8 לאגף השמאלי.'), (_C('y = 4x-3', x=2, y=5), 'המשוואה: אותו שיפוע, $b$ אחר.')]),
 ('3-14', 15, 'מצאו את משוואת הישר שמאונך לישר $y = {f|1|3}x + 2$ ועובר דרך הנקודה $(1, 4)$.', '~', 'y=-3x+7', [(_C('m = -3', m=-3), 'מאונך: הופכים את $1/3$ ל-$3/1$, ומחליפים סימן: $-3$.'), ('{f|1|3}·(-3) = -1', 'בדיקה: מכפלת השיפועים היא $-1$.'), (_C('4 = -3·1+b', b=7), 'מציבים $m = -3$ ואת $(1, 4)$.'), (_C('4+3 = b', b=7), 'מעבירים את $-3$ לאגף השמאלי. הוא הופך ל-$+3$.'), (_C('y = -3x+7', x=1, y=4), 'המשוואה.')]),
 ('3-15', 16, 'מצאו את נקודת החיתוך של שני הישרים.', 'y=3x-4;y=-x+8', {'x': '3', 'y': '5'}, [('{h|3x-4} = -x+8', 'מציבים את $y$ של הישר הראשון במשוואה של השני.'), ('3x+x = 8+4', 'מעבירים: $-x$ שמאלה, $-4$ ימינה. כל איבר שעובר מחליף סימן.'), ('4x = 12 @:4', 'מכנסים.'), ('x = 3', 'מחלקים ב-4.'), ('y = 3·3-4 = 5', 'חוזרים לביטוי של הישר הראשון.'), ('-3+8 = 5', 'בדיקה בישר השני.')]),
